
import subprocess

hex_str = "".replace("\n", "").replace(" ", "")
length_bytes = 714  # 要截取的字节数
hex_needed = length_bytes * 2  # 每字节2个hex字符
# 截取指定长度
payload = hex_str[:hex_needed]
# 调用命令行将 hex 转成二进制 bplist
proc = subprocess.run(
    ["xxd", "-r", "-p", "-", "inv.bplist"],
    input=payload.encode(),
    check=True
)
print(f"写入 inv.bplist（{length_bytes} bytes）成功")

